const fs = require('node:fs')
const assert = require('node:assert/strict')
const route = fs.readFileSync('app/api/medicao-final/ler-trena/route.ts', 'utf8')
const helper = fs.readFileSync('lib/ai/trenaVisionGratis.ts', 'utf8')
assert.match(route, /consultarTrenaGratisComAlternativa/)
assert.doesNotMatch(route, /consultarOpenCode\(/)
assert.match(route, /Foto preservada/)
assert.match(helper, /GATEWAY_FREE_VISION = 'inclusionai\/ling-3\.0-flash-vl-free'/)
assert.match(helper, /vercel-gateway-free-vision/)
assert.match(helper, /consultarOpenCodePublicFree/)
assert.doesNotMatch(helper, /consultarOpenCode\(/)
assert.doesNotMatch(helper, /OPENCODE_SERVER_PASSWORD/)
assert.match(helper, /max_tokens: 350/)
console.log('PASS: trena utiliza apenas leitura de visao gratuita, sem tunel temporario ou modelo pago.')
